from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    seen=[[False]*w for _ in range(h)]
    # exterior 0 flood with 4-connectivity
    q=deque()
    for r in range(h):
        for c in (0,w-1):
            if grid[r][c]==0 and not seen[r][c]: seen[r][c]=1;q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if grid[r][c]==0 and not seen[r][c]: seen[r][c]=1;q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and not seen[nr][nc]:
                seen[nr][nc]=1;q.append((nr,nc))
    # label components of 1 pixels, determine which border enclosed (non-exterior) zeros
    vis1=[[False]*w for _ in range(h)]
    qualifying=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=1 or vis1[r][c]: continue
        comp=[];vis1[r][c]=1;q=deque([(r,c)])
        while q:
          x,y=q.popleft();comp.append((x,y))
          for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            nx,ny=x+dx,y+dy
            if 0<=nx<h and 0<=ny<w and grid[nx][ny]==1 and not vis1[nx][ny]: vis1[nx][ny]=1;q.append((nx,ny))
        qualifies=any(0<=x+dx<h and 0<=y+dy<w and grid[x+dx][y+dy]==0 and not seen[x+dx][y+dy]
                      for x,y in comp for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)))
        if qualifies: qualifying.append(comp)
    # Paint cells near the walls of hole-bearing components; interior/exterior differ by flood class.
    for comp in qualifying:
      for r,c in comp:
        for dr in (-1,0,1):
          for dc in (-1,0,1):
            nr,nc=r+dr,c+dc
            if (dr or dc) and 0<=nr<h and 0<=nc<w and grid[nr][nc]==0:
              out[nr][nc]=3 if not seen[nr][nc] else 2
    return out

